(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["pt"] = {"ui":{"skip":"Saltar para o conteúdo","back":"← Voltar ao AI-gile","lang.button":"Idioma: {name}","lang.dialog":"Escolhe um idioma","lang.search":"Pesquisar idiomas","lang.none":"Nenhum idioma encontrado","lang.notYet":"{name} ainda não está traduzido","theme.aria":"Mudar de tema: claro, escuro ou preto","theme.toLight":"Mudar para o tema claro","theme.toDark":"Mudar para o tema escuro","theme.toBlack":"Mudar para o tema preto (preto a sério, ideal para ecrãs OLED)","words.underline":"Sublinhar estas palavras na página","words.underlineHelp":"Passa o rato ou toca numa palavra pontilhada para veres o que significa.","words.col.todo":"Cartões escolhidos para agora: a equipa começa por estes a seguir.","words.col.doing":"Uma IA está a trabalhar neste cartão neste momento.","words.col.review":"Uma IA acabou o trabalho; outra verifica-o antes de chegar a ti.","words.col.verify":"À tua espera: experimenta e diz se funciona.","words.col.team":"As tuas notas ou respostas, à espera de que a equipa as apanhe.","words.col.done":"Concluído e aceite.","index.title":"AI-gile: a tua equipa de dev com IA, num só quadro","index.description":"O AI-gile é um quadro kanban para equipas de código com IA. Elas trabalham enquanto dormes; recebes uma pilha curta de coisas para decidir, testar e aceitar.","hero.logoAlt":"Ícone do quadro AI-gile","hero.h1.html":"A tua equipa de dev com IA, num só&nbsp;quadro.","hero.alpha":"🐣 Pré-alfa fechado","hero.alphaTitle":"Cedo e inacabado: obrigado por experimentares!","hero.lede":"Constroem enquanto dormes. Acordas com uma pilha curta: algumas perguntas, algumas coisas para testar, um ou dois diamantes roxos. Clica, aceita, volta ao teu café.","dl.windows":"Aplicação para Windows","dl.browser":"Usar no navegador","dl.messenger":"📱 Messenger para o teu telemóvel","dl.soon":"Em breve","dl.notify":"🔔 Avisem-me quando abrir","dl.notifySmall":"Alfa ou beta","hero.secondary":"Ágil, mas a equipa nunca precisa de café em pé para a reunião diária. (Fazem-na na mesma.)","pitch.h2":"O AI-gile em quantas palavras quiseres","pitch.lede":"Escolhe um tamanho, de uma palavra a 144. Cada tamanho é uma descrição própria, escrita para ele. Arrasta o cursor ou usa as setas do teclado.","pitch.rangeLabel":"Tamanho em palavras","pitch.dice":"🎲 outra versão","pitch.words.one":"{n} palavra","pitch.words.other":"{n} palavras","pitch.letters.one":"{n} letra","pitch.letters.other":"{n} letras","pitch.chars.one":"{n} caráter","pitch.chars.other":"{n} carateres","count.line.html.one":"{n} cartão no quadro neste momento","count.line.html.other":"{n} cartões no quadro neste momento","people.humans.html.one":"👥 {n} humano","people.humans.html.other":"👥 {n} humanos","people.agents.html.one":"🤖 {n} agente","people.agents.html.other":"🤖 {n} agentes","people.working.html.one":"⚡ {n} a trabalhar neste momento","people.working.html.other":"⚡ {n} a trabalhar neste momento","pre.title":"AI-gile: há algo a ser construído","pre.description":"Há algo a ser construído aqui: um quadro onde equipas de IA constroem o que pedes e te vão ensinando pelo caminho. Por agora, pré-alfa fechado entre amigos.","pre.h1":"Há algo a ser construído aqui. 🤫","pre.line":"Um quadro onde equipas de IA constroem o que pedes e te vão ensinando pelo caminho. Por agora, pré-alfa fechado entre amigos.","pre.btn":"🔔 Avisem-me quando abrir","pre.peek":"Atrás do vidro: o quadro verdadeiro, em direto. Cada cartão é uma barra colorida.","pre.peekFake":"Atrás do vidro: assim é um quadro a trabalhar.","features.aria":"O que faz","f.pile.h":"Uma pilha só para ti","f.pile.html":"<b>Para ti</b> reúne tudo o que está à tua espera, em todos os projetos: perguntas, coisas para testar, tarefas que só um humano pode fazer. A tua fila diz o que vem a seguir e quanto tempo demora.","f.sleep.h":"Equipas que trabalham enquanto dormes","f.sleep.p":"Cada projeto tem um líder e uma equipa de agentes de IA. Comenta num cartão e a equipa acorda, faz o trabalho e devolve-o com passos que um humano cansado consegue seguir.","f.tester.h":"Um testador de IA verifica primeiro","f.tester.p":"Antes de chegar a ti, um testador segue os passos numa cópia da aplicação e mostra o que viu, com uma captura de ecrã. Passa pelos aprovados e aceita com um clique.","f.proof.h":"Provas, não promessas","f.proof.p":"Cada entrega mostra o que mudou: os ficheiros, o diff, as capturas de ecrã. Sem abrir cada aplicação para ver se já está pronto.","f.chat.h":"Conversa com os teus líderes","f.chat.p":"Uma barra ao estilo do Discord: um ícone por projeto, diamantes roxos para o que precisa de ti. Manda uma ideia a um líder; ele transforma-a em cartões e num plano, com um botão ✅ Go.","f.tidy.h":"Mantém-se arrumado","f.tidy.p":"Cartões parecidos juntam-se num só, títulos confusos são corrigidos e uma verificação de tokens mantém o código enxuto. Menos coisas para alternar, menos em que pensar.","f.private.h":"Teu, no teu computador","f.private.li1":"O quadro corre na tua própria máquina e só responde a ti.","f.private.li2":"As DMs privadas entre pessoas têm encriptação de ponta a ponta.","f.private.li3":"Sem contas, sem rastreadores, sem cookies.","f.lang.h":"Na tua língua","f.lang.p":"Mais de 120 idiomas, do holandês, galês e japonês ao pirata, Yoda e klingon, com uma troca rápida para inglês no jargão técnico.","f.service.h":"De uma ideia a um serviço a sério","f.service.p":"Construíste com IA algo que as pessoas já usam? Marca-o como serviço e o quadro ajuda-te a geri-lo bem: verificações de disponibilidade, uma página de estado pública, incidentes com relatório, alterações que precisam de um Avançar, cópias de segurança verificadas todos os dias. A Ajuda ensina cada passo pelo caminho.","msgr.h2":"AI-gile Messenger: a tua equipa no bolso","msgr.p1":"Fala com a tua equipa de IA sem abrir o quadro. Conversa com os líderes dos teus projetos e com os teus amigos, vê os passos de teste de um cartão e responde-lhes, tudo a partir do telemóvel.","msgr.p2":"Para o emparelhar, digitaliza um código QR no teu quadro. Primeira vez? Um chat de demonstração simpático mostra-te tudo.","msgr.when":"Primeiro Android, depois uma versão web para telemóveis e iPhone.","msgr.who":"O teu líder de projeto","msgr.b1":"A correção do modo escuro está pronta. Queres os passos de teste?","msgr.b2":"Sim, por favor!","msgr.b3":"1. Abre as Definições. 2. Escolhe Escuro. Parece-te bem?","tl.aria":"Cronologia, da primeira conversa ao plano","tl.h2":"Da primeira conversa ao que vem a seguir","tl.lede":"Datas e horas reais, no teu fuso horário. Depois de hoje é o plano, sem datas prometidas.","tl.today":"Hoje","tl.planned":"planeado","tl.doing":"em curso","tl.cards.one":"{n} cartão","tl.cards.other":"{n} cartões","join.h2":"Junta-te","join.lede":"O AI-gile está a ser construído por um esquisitão barbudo com AuDHD e algumas batalhas com a saúde mental, e por muitos agentes pacientes. Por agora é privado, num alfa fechado com amigos. Queres experimentar quando abrir?","join.btn":"Registar interesse","join.small":"Escrevemos-te por e-mail, mais nada","footer.tag":"AI-gile. Sem rastreadores, sem cookies, sem café em pé.","footer.licence":"Licença comercial","footer.status":"Estado","footer.privacy":"O que guardamos","footer.thanks":"Chamadas graças ao ChilledChat","form.sending":"A enviar…","form.failed":"Não resultou: tenta outra vez mais tarde.","form.offline":"Não foi possível contactar o AI-gile: tenta outra vez mais tarde.","form.keep":"Só usamos isto para te responder e depois apagamos. Sem rastreadores, sem cookies.","form.keepLink":"O que guardamos","interest.title":"AI-gile: avisem-me quando o alfa abrir","interest.description":"Deixa o teu e-mail para saberes quando o alfa ou beta fechado do AI-gile abrir.","interest.h1":"🔔 Avisem-me quando abrir","interest.lede":"O AI-gile está em pré-alfa fechado. Deixa o teu e-mail e escrevemos uma vez, quando houver lugar para ti.","interest.email":"O teu e-mail","interest.which":"Que teste?","interest.alpha":"Alfa fechado: cedo, cru, com muitas mudanças","interest.beta":"Beta: mais firme, mais tarde","interest.both":"Tanto faz, o que vier primeiro","interest.submit":"Pôr-me na lista","interest.thanks":"Obrigado! Estás na lista.","licence.title":"AI-gile: licença comercial","licence.description":"Vais usar o AI-gile na tua empresa? Pede uma licença comercial gratuita.","licence.h1":"📜 Licença comercial","licence.lede":"Vais usar o AI-gile no trabalho? Conta-nos quem és e o que fazes. Se fizer algum bem, a licença é gratuita.","licence.company":"Empresa","licence.website":"Site","licence.what":"O que fazes","licence.how":"Como isso ajuda o mundo","licence.email":"E-mail","licence.submit":"Pedir","licence.thanks":"Obrigado! Respondemos por e-mail.","status.title":"Estado do AI-gile","status.h1":"Estado do AI-gile","status.quiet":"Tudo calmo","status.intro":"O AI-gile está a funcionar neste momento? Esta página verifica o site, a partilha de quadros, as chamadas e a transferência a cada 5 minutos.","status.up":"A funcionar (respondeu em {ms} ms)","status.slow":"Não respondeu à última verificação, a tentar de novo","status.down":"Em baixo: não respondeu às duas últimas verificações","status.svc.web":"Site","status.svc.web.offers":"Este site: o que é o AI-gile e o formulário de interesse","status.svc.boards":"Partilha de quadros","status.svc.boards.offers":"Quadros públicos, mensagens entre amigos e convites","status.svc.calls":"Chamadas","status.svc.calls.offers":"Voz, vídeo e partilha de ecrã no AI-gile","status.svc.download":"Transferência","status.svc.download.offers":"O instalador para Windows e as ligações de convite","status.checking":"A verificar…","status.offline":"Não é possível contactar o serviço de estado neste momento (a tentar de novo)","status.updated":"atualizado {ago}","status.justNow":"agora mesmo","status.min":"há {n} min","status.hours":"há {n} h","status.days":"há {n} d","privacy.title":"AI-gile: o que guardamos","privacy.h1":"O que guardamos","privacy.lede":"Versão curta: só o que nos envias, e não por muito tempo.","privacy.only":"Só o que nos envias: o que escreves num formulário, como o teu e-mail. Mais nada sobre ti.","privacy.sealed":"É selado para que o nosso servidor não o consiga ler: no teu navegador, antes de sair (num navegador mais antigo, no momento em que chega). Só o nosso próprio quadro o consegue abrir.","privacy.server":"É apagado do servidor assim que chega ao nosso quadro. O que lá estiver ao fim de 30 dias é apagado na mesma.","privacy.board":"Guardamo-lo no nosso quadro só até te respondermos e depois apagamo-lo também de lá.","privacy.none":"Sem rastreadores, sem cookies, sem análises.","privacy.local":"O teu idioma e a escolha de tema claro ou escuro ficam no teu próprio navegador. Nunca nos são enviados.","privacy.ask":"Queres que desapareça mais cedo? Responde ao nosso e-mail e diz-nos.","live.h2":"Veja a ser construído, em direto","live.caption":"Cada cartão está escondido: vê a forma do trabalho, não as palavras.","live.watching.one":"em direto: {n} a ver","live.watching.other":"em direto: {n} a ver","live.last.now":"Último cartão movido agora mesmo","live.last.min.one":"Último cartão movido há {n} min","live.last.min.other":"Último cartão movido há {n} min","live.last.hour.one":"Último cartão movido há {n} hora","live.last.hour.other":"Último cartão movido há {n} horas","live.last.day.one":"Último cartão movido há {n} dia","live.last.day.other":"Último cartão movido há {n} dias","live.offline":"O quadro em direto está a fazer uma pausa. Volte em breve.","live.cols":"Backlog|A fazer|Em curso|A equipa verifica|Para testares|Para a equipa|Concluído"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robôs.","Delegado."]},{"n":2,"texts":["Kanban robótico.","Agentes, organizados.","Ideias, construídas."]},{"n":3,"texts":["Kanban para robôs.","Ideias viram funcionalidades.","Kanban de agentes, grátis."]},{"n":5,"texts":["Quadro kanban gerido por agentes.","Tu escreves cartões. Agentes constroem.","Grátis, local, testado, um pouco parvo."]},{"n":8,"texts":["Um kanban grátis onde agentes de IA trabalham.","Escreve uma ideia. Agentes constroem. Tu aceitas.","Ágil para um humano e muitos robôs pacientes."]},{"n":13,"texts":["Um quadro kanban no teu computador, onde agentes de IA pegam nos cartões.","Escreve uma ideia. Uma equipa de agentes constrói. Um testador verifica.","Grátis, sem contas, sem rastreadores: um quadro, uns robôs e tu no comando."]},{"n":21,"texts":["O AI-gile é um quadro kanban para trabalhar com agentes de código de IA. Eles pegam nos cartões; tu testas e aceitas.","Cada projeto tem um líder e uma equipa de agentes de IA. Comenta em qualquer cartão e a equipa mete mãos à obra.","Um quadro pessoal e gratuito que corre no teu próprio computador. Quem trabalha são robôs. Quem diz que sim és tu."]},{"n":34,"texts":["Pões ideias num quadro. Uma equipa de agentes de IA transforma-as em funcionalidades que funcionam, testa tudo e devolve com passos para experimentares. Nada conta como pronto até dizeres que sim.","O AI-gile é um quadro kanban caseiro que o Rich construiu com muita ajuda dos agentes que agora gere. É gratuito, corre no teu computador e é partilhado com amigos, não vendido.","Imagina um quadro kanban normal, com colunas do Backlog até Concluído, só que os cartões são pegos por agentes de IA. Contam o andamento, perguntam quando encravam e esperam sempre pelo teu polegar para cima."]},{"n":55,"texts":["O AI-gile é um quadro kanban em que a equipa é feita de agentes de IA. Cada projeto tem um líder que planeia o trabalho e ajudantes que o constroem. Quando uma funcionalidade fica pronta, um testador de IA experimenta-a e tira uma captura de ecrã, e depois cai na tua pilha. Aceita, ou comenta e eles refazem.","Começou como a maneira de uma pessoa acompanhar várias sessões de código com IA ao mesmo tempo e cresceu até ser um quadro a sério. Corre na tua máquina, não pede conta e não tem rastreadores. É grátis para amigos e curiosos. Também está inacabado, por isso espera arestas e uma surpresa de vez em quando.","Sejamos honestos. Ainda tens de ter as ideias e ainda tens de verificar os resultados. O que o AI-gile faz é tudo o que fica pelo meio: mantém os cartões por ordem, acorda o agente certo quando comentas, mostra exatamente o que mudou e junta tudo numa pilha curta para ti."]},{"n":89,"texts":["O AI-gile é um quadro kanban gratuito que corres no teu próprio computador. Em vez de pessoas, cada projeto tem uma equipa de agentes de IA: um líder que transforma as tuas ideias em cartões e num plano, e ajudantes que pegam nos cartões por ordem de prioridade. Quando algo fica pronto, um testador de IA segue os passos de teste e mostra o que viu. Depois fica à espera numa pilha chamada Para ti. Aceitas, ou comentas e a equipa tenta outra vez. Nada chega a Concluído sem ti.","Alguns recursos que talvez não esperes. Um vigia da noite mantém a coluna A fazer abastecida enquanto dormes, escolhendo cartões que não precisam de resposta tua. Um contador de tokens mostra quanto os agentes gastaram hoje e esta semana, e o Modo Sem Tokens manda-os parar de gastar. Podes conversar com amigos, e as mensagens privadas têm encriptação de ponta a ponta. O quadro fala cerca de 120 idiomas, entre eles holandês, flamengo, pirata e klingon. Nada disto custa um cêntimo, e ninguém te quer vender nada.","O AI-gile é um projeto pequeno e pessoal, não uma empresa. O Rich queria cuidar de vários projetos de código com IA sem abrir cada aplicação para espreitar, por isso ele e os agentes construíram um quadro para isso e depois usaram o quadro para construir o resto dele próprio. Está em pré-alfa fechado, ou seja, funciona, quase sempre, para um punhado de amigos. Não há página de preços, newsletter nem plano de crescimento. Se te parece útil, pede para experimentar quando abrir um pouco mais."]},{"n":144,"texts":["O AI-gile é um quadro kanban para um humano e muitos agentes de IA. Corre no teu próprio computador e é totalmente gratuito. Adicionas projetos, e cada projeto ganha um líder e uma equipa pequena. Conversas com o líder, mais ou menos como no Discord, e descreves uma ideia; o líder transforma-a em cartões e num plano, e espera que carregues em Go. A equipa vai passando pelos cartões por ordem de prioridade, usando uma linha de comandos simples feita para modelos de linguagem. Antes de qualquer coisa voltar para ti, um testador de IA segue os passos numa cópia da aplicação e anexa uma captura de ecrã. O trabalho pronto cai na tua pilha com os ficheiros alterados e o diff. Aceitas, ou deixas um comentário e a equipa acorda e tenta de novo. Só tu podes mover um cartão para Concluído.","Um dia com o AI-gile, mais ou menos. À noite deixas alguns comentários: este botão está no sítio errado, aquela lista devia estar ordenada, podíamos ter um modo escuro. Vais dormir. Os agentes lêem os comentários, fazem as alterações, testam e devolvem-te tudo. Se o A fazer esvazia, o vigia da noite volta a enchê-lo com cartões do backlog que não precisam de resposta tua. De manhã há uma pilha curta: algumas perguntas e algumas coisas para experimentar, cada uma com passos que uma pessoa ensonada consegue seguir e uma captura de ecrã a funcionar. Passas por tudo, aceitas o que está bom e devolves o resto. Um contador de tokens mostra o que tudo isto gastou, e o Modo Sem Tokens existe para as semanas magras. Depois tomas o pequeno-almoço, e aí os agentes ainda não ajudam.","Primeiro, o que o AI-gile não é. Não é uma startup, não está à venda e ninguém recolhe os teus dados. É um quadro gratuito que corre no teu computador, sem contas, sem rastreadores e sem cookies. O que é: um lugar arrumado para ver todos os teus projetos de código com IA de uma vez, com uma equipa de agentes a tratar dos cartões e tu a tomar as decisões. Junta cartões parecidos, corrige títulos confusos e vigia quão enxuto o código se mantém. Fala cerca de 120 idiomas, do holandês e do flamengo ao pirata e ao klingon. Os amigos podem trocar mensagens, em privado e encriptadas. Foi construído pelo Rich e por muitos agentes pacientes, usando-se a si próprio quase sempre. Está em pré-alfa fechado, por isso ainda é cru em alguns pontos. Se te parece divertido, pede com jeitinho e talvez entres mais cedo."]}],"quips":{"1":"Uma palavra. Ousado. Talvez demasiado ousado.","3":"Três palavras. Já mais honesto do que a maioria das páginas de produto.","8":"Oito palavras. Ainda mais curto do que uma reunião diária.","21":"Os tamanhos são story points, já agora. Claro que são.","55":"Cinquenta e cinco palavras. Dois cartões ficaram prontos enquanto lias.","144":"Esta é a longa. Não existe 233. Os agentes foram dormir."}},"timeline":{"first-idea.name":"A primeira ideia","first-idea.line":"A primeiríssima conversa, antes de existir qualquer código.","first-board.name":"Primeiro quadro","first-board.line":"Um quadro que acompanha a sua própria construção: cartões, colunas, arrastar e largar, projetos.","team-roles.name":"Equipa e funções","team-roles.line":"Perfis de agentes, modelos de equipa, espaços e quem faz o quê.","install.name":"Instalação e versões","install.line":"Um zip que um amigo instala, com atualização automática, canais e voltar atrás.","usage-saver.name":"Poupança de uso","usage-saver.line":"Medir o custo de cada execução, manter o código enxuto, poupar o teu limite.","friends.name":"Amigos e partilha","friends.line":"DMs privadas, um relay baralhado, convites, funções e projetos partilhados.","languages.name":"Idiomas","languages.line":"Todo o texto dos ecrãs num ficheiro de idioma, começando pelo holandês e o flamengo.","ai-tester.name":"Testador de IA","ai-tester.line":"Um testador verifica cada entrega primeiro e mostra o que viu.","website.name":"O site","website.line":"aigile.lol, a página de apresentação e esta cronologia.","streaming.name":"Chat e emissão","streaming.line":"Discord, Twitch, OBS, modo streamer, GIFs e emojis.","no-ai.name":"Edição sem IA","no-ai.line":"Um quadro para quem programa sem IA, e quadros públicos.","night-watch.name":"Vigia da noite","night-watch.line":"Um vigia e Scrum Master mantêm as equipas no rumo enquanto dormes.","p-more.name":"Tudo o resto","p-more.line":"Ideias mais pequenas ainda à espera da sua vez.","p-android.name":"Telemóvel e Android","p-android.line":"Acede ao teu quadro pelo telemóvel e, depois, numa aplicação Android nativa.","p-release.name":"Alfa e mais além","p-release.line":"Alfa fechado, o site no ar e depois o beta.","p-languages.name":"Mais idiomas","p-languages.line":"130 línguas e um modo de imersão para quem está a aprender.","p-engines.name":"Mais motores de IA","p-engines.line":"Escolhe Claude, Codex, Gemini, Copilot ou Cursor para cada agente.","p-pro.name":"Prática profissional","p-pro.line":"Etiquetas de risco, portões de merge, cartões de incidente e proteções.","p-self.name":"A cuidar de ti","p-self.line":"Modo cansado, lembretes de autocuidado e 4:20.","p-servers.name":"Servidores e escala","p-servers.line":"Definições globais de servidor, funções e planeamento para crescer.","p-livestream.name":"Extras de emissão","p-livestream.line":"Chat da Twitch, emojis personalizados e uma vista pública em direto."},"words":{"button":"📖 Jargão técnico","h":"📖 Palavras explicadas","intro":"As palavras que encontras no AI-gile, em linguagem simples: construir, alterar com segurança, manter a funcionar para quem usa e trabalhar em equipa com IA.","search":"Pesquisar uma palavra…","none":"Nenhuma palavra corresponde.","close":"Fechar","count":{"one":"{count} palavra","other":"{count} palavras"},"groups":[{"id":"build","name":"🛠️ Construir"},{"id":"change","name":"🔀 Alterar com segurança"},{"id":"run","name":"🛎️ Manter um serviço"},{"id":"team","name":"🤝 Trabalhar em equipa (e com IA)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"A pasta de código do projeto e todo o seu histórico de commits, normalmente também guardada no GitHub.","also":["repositório","repository"]},{"id":"branch","g":"build","word":"Branch","text":"Uma linha de trabalho separada no código, para fazer alterações sem tocar na versão principal.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Um instantâneo guardado do código, com uma nota curta do que mudou. Podes sempre voltar a um deles.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Enviar os instantâneos guardados (commits) deste computador para o GitHub, para ficarem com cópia de segurança e partilhados."},{"id":"merge","g":"build","word":"Merge","text":"Integrar as alterações de um branch na versão principal."},{"id":"pr","g":"build","word":"Pull request","text":"Pedir que as alterações de um branch sejam verificadas e integradas na versão principal.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Arrumar o código sem mudar o que ele faz: ficheiros mais pequenos, nomes mais claros, menos repetição."},{"id":"bug","g":"build","word":"Bug","text":"Algo que não funciona como devia.","also":["bugs"]},{"id":"test","g":"build","word":"Teste","text":"Experimentar um trabalho terminado para verificar se faz o que foi pedido, antes de o aceitares.","also":["testes","testar","testares"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Sigla de quality assurance, garantia de qualidade: as verificações automáticas que correm antes de qualquer coisa ir para o ar. Quando o QA está vermelho, algo falhou, e não pode ir para o ar até isso ser corrigido.","also":["garantia de qualidade","verificações de qualidade"]},{"id":"deploy","g":"change","word":"Deploy","text":"Pôr uma nova versão em produção, por exemplo num servidor onde as pessoas a usam."},{"id":"release","g":"change","word":"Lançamento","text":"Um pacote de trabalho terminado, com nome, que vai para o ar de uma vez, com notas curtas sobre o que mudou. 🚀 Lançamentos escreve as notas a partir dos cartões feitos.","also":["lançamentos","release","releases"]},{"id":"rollback","g":"change","word":"Rollback","text":"Voltar à última versão que funcionava quando uma nova causa problemas. No AI-gile, isto gera uma lista de verificação com os passos para desfazer escritos em cada alteração.","also":["reverter","reversão","voltar atrás"]},{"id":"live","g":"change","word":"Em produção","text":"A versão verdadeira que as pessoas usam, ao contrário de uma cópia para experimentar coisas. Os programadores chamam-lhe produção.","also":["produção","no ar","live"],"noTip":1},{"id":"change","g":"change","word":"Alteração","text":"Uma alteração planeada a algo de que as pessoas dependem, escrita primeiro: o quê, porquê, o risco, quando e como desfazer. Começa uma com 🔀 Propor uma alteração.","also":["alterações","pedido de alteração","mudança","change request"],"noTip":1},{"id":"risk","g":"change","word":"Risco","text":"Algo que pode correr mal, pontuado pela probabilidade e pela gravidade. ⚠️ Riscos guarda-os numa só lista, da pontuação mais alta para a mais baixa, cada um com uma data para voltar a olhar.","also":["riscos","registo de riscos"]},{"id":"chgwin","g":"change","word":"Janela de alterações","text":"As horas em que as alterações podem ir para o ar, como uma terça-feira à noite sossegada. Fora de uma janela, um cartão de alteração não pode ser terminado, a não ser que seja uma emergência.","also":["janelas de alterações","change window"]},{"id":"gonogo","g":"change","word":"Avançar / não avançar","text":"Uma votação rápida mesmo antes de uma alteração ir para o ar: cada pessoa que tem de aprovar diz Avançar ou Não avançar. Só avança quando todos concordam.","also":["go/no go","go-no-go","go / no go"]},{"id":"approval","g":"change","word":"Aprovação","text":"Esperar por um sim antes de o trabalho começar. Um cartão aberto por um amigo, ou uma alteração, espera em ✅ Aprovações até o aprovares ou recusares.","also":["aprovações"]},{"id":"quiettime","g":"change","word":"Hora de silêncio","text":"Um período, como uma transmissão, uma demo ou a noite, em que nada vai para o ar. As equipas continuam a trabalhar e a testar, mas ir para o ar espera até acabar. Noutros sítios chama-se congelamento de alterações.","also":["horas de silêncio","congelamento de alterações","change freeze"]},{"id":"service","g":"run","word":"Serviço","text":"Algo que construíste e de que as pessoas dependem, como um site ou uma app, cuidado para continuar a funcionar. Marca “Este projeto é um serviço” e diz o que oferece, quem o usa e quem está de prevenção.","also":["serviços"]},{"id":"uptime","g":"run","word":"Verificação de disponibilidade","text":"Uma verificação automática, de poucos em poucos minutos, de que o teu serviço ainda responde. Se falhar várias vezes seguidas, o AI-gile abre sozinho um cartão de incidente.","also":["uptime","disponibilidade"]},{"id":"statuspage","g":"run","word":"Página de estado","text":"Uma página pública que mostra se um serviço está a funcionar (verde, laranja ou vermelho), com a última atualização, para quem o usa poder ver em vez de perguntar.","also":["páginas de estado","página de status","status page"]},{"id":"desk","g":"run","word":"Service desk","text":"Onde chegam as perguntas e os relatos das pessoas que usam o teu serviço. O AI-gile classifica cada um como pedido, incidente ou ideia, e avisa quando parece algo que já foi relatado.","also":["service desks","secretária","balcão de atendimento","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Pedido de serviço","text":"Alguém a pedir algo normal, como uma conta nova ou uma pequena ajuda, em vez de avisar que algo está avariado. Espera pela sua vez; um incidente passa à frente.","also":["pedidos de serviço","pedido"]},{"id":"incident","g":"run","word":"Incidente","text":"Algo que está avariado agora mesmo para quem o usa, como o site em baixo. Um cartão de 🔥 incidente passa à frente da fila: pô-lo a funcionar outra vez vem primeiro.","also":["incidentes","avaria","em baixo"]},{"id":"major","g":"run","word":"Incidente grave","text":"Um incidente grande: muitas pessoas afetadas, ou dinheiro ou dados em risco. Um botão põe todas as equipas nele (enxame), acorda quem está de prevenção e pede uma atualização de estado a cada 30 minutos.","also":["incidentes graves","major incident"]},{"id":"oncall","g":"run","word":"De prevenção","text":"Ser quem responde quando algo avaria, mesmo à noite. Cada serviço tem um membro da equipa de prevenção, que é acordado primeiro nos incidentes desse serviço.","also":["prevenção","on call","on-call","piquete"]},{"id":"replyby","g":"run","word":"Prazo de resposta","text":"Quanto tempo um cartão pode esperar por uma primeira resposta, por exemplo uma hora para um incidente. Depois disso ganha um relógio vermelho, para nada ficar esquecido em silêncio. Também se chama objetivo de resposta.","also":["prazos de resposta","objetivo de resposta","tempo de resposta"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Um olhar rápido para trás depois de um incidente: o que aconteceu, o que ajudou e o que mudar, sem culpar ninguém. Um incidente não pode ser fechado sem um.","also":["post-mortems","postmortem","revisão pós-incidente"]},{"id":"problem","g":"run","word":"Problema","text":"A causa escondida por trás de um ou mais incidentes. Um cartão de 🧩 problema junta incidentes que continuam a voltar, para a causa ser encontrada e corrigida de vez.","also":["problemas"],"noTip":1},{"id":"rootcause","g":"run","word":"Causa raiz","text":"A verdadeira razão de algo ter avariado, não só o que se viu a correr mal. Corrige a causa raiz e o incidente deixa de voltar.","also":["causas raiz","root cause"]},{"id":"workaround","g":"run","word":"Solução provisória","text":"Uma forma de manter as coisas a funcionar até a correção verdadeira estar pronta, como reiniciar algo quando bloqueia. Fica escrita no cartão do problema, para ninguém ter de a descobrir outra vez.","also":["soluções provisórias","workaround","contorno"]},{"id":"knownerror","g":"run","word":"Erro conhecido","text":"Um problema cuja causa já se percebe e que tem uma solução provisória, mas ainda não está corrigido. 🧩 Erros conhecidos lista-os, para todos usarem a solução provisória em vez de voltarem a investigar.","also":["erros conhecidos","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Instruções passo a passo para resolver um tipo de problema conhecido, para ser feito da mesma maneira, depressa, todas as vezes. Depois de um incidente grande, a equipa pode propor um para lhe dares o OK.","also":["runbooks","manual de procedimentos","guião"]},{"id":"ci","g":"run","word":"Item de configuração","text":"Uma coisa de que o teu serviço depende, como um servidor, um domínio, um certificado, uma chave ou um fornecedor. 🗂️ Itens de configuração lista-os por serviço, para veres o que um incidente afeta e o que precisa de ser renovado ou de ter cópia de segurança.","also":["itens de configuração"]},{"id":"expiry","g":"run","word":"Data de validade","text":"O AI-gile está atento a datas como o fim da validade de um certificado ou de um domínio. A 30 dias dessa data cria um cartão para o renovar, para que nada deixe de funcionar de surpresa.","also":["datas de validade","validade","expiração","vigilância de validade"]},{"id":"backup","g":"run","word":"Cópia de segurança","text":"Uma cópia guardada dos teus dados de antes, para recorrer se algo se perder ou estragar. O AI-gile faz todos os dias uma cópia de segurança dos teus quadros.","also":["cópias de segurança","backup","backups"]},{"id":"restore","g":"run","word":"Restauro","text":"Repor os dados a partir de uma cópia de segurança. Uma cópia só conta mesmo quando sabes que pode ser restaurada, por isso vale a pena experimentar de vez em quando.","also":["restaurar","restaurado","reposição","restore"]},{"id":"svcreview","g":"run","word":"Revisão do serviço","text":"Um olhar para trás sobre um mês de um serviço: incidentes abertos e resolvidos, a rapidez com que as pessoas tiveram resposta, disponibilidade e tokens usados. A Revisão mensal mostra isto para cada serviço.","also":["revisões do serviço","revisão mensal","revisões mensais"]},{"id":"accessreview","g":"run","word":"Revisão de acessos","text":"Verificar a cada 90 dias quem ainda consegue entrar: ligações de partilha, papéis dos amigos e segredos guardados. Guardas ou removes cada um, para que acessos antigos não fiquem esquecidos.","also":["revisões de acessos","revisão de acesso"]},{"id":"improvements","g":"run","word":"Lista de melhorias","text":"Tudo o que a equipa decidiu melhorar, num só sítio: sugestões da retrospetiva, ações das revisões e correções de problemas, cada uma com o seu estado. Está em 📈 Melhorias.","also":["listas de melhorias","melhorias"]},{"id":"tokencap","g":"run","word":"Limite de tokens","text":"Um limite mensal para os tokens que os agentes de um serviço podem usar. Aos 80% recebes um aviso; aos 100% o trabalho deles em segundo plano espera pelo mês seguinte ou até aumentares o limite.","also":["limites de tokens","limite mensal de tokens"]},{"id":"backlog","g":"team","word":"Backlog","text":"Ideias e trabalho que ainda não foram planeados. Nada ali é trabalhado até passar para A fazer."},{"id":"sprint","g":"team","word":"Sprint","text":"Um período curto de trabalho (muitas vezes uma ou duas semanas) com um conjunto combinado de cartões para concluir.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"Um ponto de situação rápido: o que cada membro da equipa fez, o que faz a seguir e o que o está a travar.","also":["standup","stand-ups","daily"]},{"id":"kanban","g":"team","word":"Kanban","text":"Um quadro com colunas (A fazer, Em curso, Concluído) onde os cartões andam da esquerda para a direita à medida que o trabalho avança."},{"id":"wip","g":"team","word":"Limite de WIP","text":"Work in progress (trabalho em curso): o máximo de cartões que uma coluna deve ter, para a equipa acabar as coisas antes de começar mais.","also":["WIP"]},{"id":"dod","g":"team","word":"Definição de Feito","text":"A lista curta da equipa do que quer dizer “terminado”, como testado e explicado, antes de um cartão te chegar. A sua gémea, a Definição de Pronto, diz quando um cartão está claro o suficiente para começar.","also":["Definition of Done","DoD","Definição de Pronto","Definition of Ready"]},{"id":"testpile","g":"team","word":"Pilha de testes","text":"Os cartões terminados à espera que os experimentes, um a seguir ao outro. Aceita um ou devolve-o com uma nota, e aparece o seguinte.","also":["pilhas de testes","test pile"]},{"id":"retro","g":"team","word":"Retrospetiva","text":"Um olhar para trás sobre a forma como a equipa trabalha, para combinar uma coisa a fazer melhor. No AI-gile, uma retrospetiva sugere uma alteração à forma de trabalhar da equipa, e tu dizes Go ou Ainda não.","also":["retro","retros","retrospetivas"]},{"id":"peerreview","g":"team","word":"Revisão por pares","text":"Um segundo par de olhos: outra IA verifica o trabalho de cada cartão antes de chegar a ti, por isso passam menos erros.","also":["revisão de código","code review","peer review"]},{"id":"swarm","g":"team","word":"Enxame","text":"Todos ao convés: cada equipa larga o resto do trabalho para ajudar num projeto urgente até ficar resolvido. Os outros projetos esperam entretanto.","also":["swarm","swarming","modo enxame"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Quem mantém o trabalho a andar: repara nos cartões parados, dá um empurrão às equipas e lembra-te do que está à espera. No AI-gile, o Lead Scrum Master faz isto em todos os projetos.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agente","text":"Uma IA que trabalha sozinha numa tarefa: lê o código, faz alterações, corre verificações e comunica o resultado.","also":["agentes","agent"]},{"id":"token","g":"team","word":"Token","text":"A unidade em que o uso da IA é contado: aproximadamente algumas letras de texto lidas ou escritas. Menos tokens, mais do teu plano por gastar.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Um pequeno comando que corre sozinho num momento definido, por exemplo quando uma sessão de IA começa, para a equipa ouvir os teus comentários.","also":["hooks"]}]}};
